@Environment(\.monarchTheme) private var theme

private struct Ticket: Identifiable {
    let id: String
    let title: String
    let tag: String
    let tone: MonarchTone
}

@State private var columns = [
    MonarchKanbanColumn(id: {{columns.0.id}}, title: {{columns.0.title}}, items: [
        Ticket(id: {{columns.0.items.0.id}}, title: {{columns.0.items.0.title}}, tag: {{columns.0.items.0.tag}}, tone: {{columns.0.items.0.tone|tone}}),
        Ticket(id: {{columns.0.items.1.id}}, title: {{columns.0.items.1.title}}, tag: {{columns.0.items.1.tag}}, tone: {{columns.0.items.1.tone|tone}}),
        Ticket(id: {{columns.0.items.2.id}}, title: {{columns.0.items.2.title}}, tag: {{columns.0.items.2.tag}}, tone: {{columns.0.items.2.tone|tone}}),
    ]),
    MonarchKanbanColumn(id: {{columns.1.id}}, title: {{columns.1.title}}, items: [
        Ticket(id: {{columns.1.items.0.id}}, title: {{columns.1.items.0.title}}, tag: {{columns.1.items.0.tag}}, tone: {{columns.1.items.0.tone|tone}}),
        Ticket(id: {{columns.1.items.1.id}}, title: {{columns.1.items.1.title}}, tag: {{columns.1.items.1.tag}}, tone: {{columns.1.items.1.tone|tone}}),
        Ticket(id: {{columns.1.items.2.id}}, title: {{columns.1.items.2.title}}, tag: {{columns.1.items.2.tag}}, tone: {{columns.1.items.2.tone|tone}}),
    ], wipLimit: {{columns.1.wipLimit}}),
    MonarchKanbanColumn(id: {{columns.2.id}}, title: {{columns.2.title}}, items: [
        Ticket(id: {{columns.2.items.0.id}}, title: {{columns.2.items.0.title}}, tag: {{columns.2.items.0.tag}}, tone: {{columns.2.items.0.tone|tone}}),
    ]),
    MonarchKanbanColumn(id: {{columns.3.id}}, title: {{columns.3.title}}, items: [Ticket]()),
